suppressPackageStartupMessages({library(data.table);library(hdf5r)});w<-'independent_validation';md<-readRDS(file.path(w,'cell_metadata.rds'));a<-readRDS(file.path(w,'cell_accounting.rds'));u<-fread(file.path(w,'assayed_frozen_universe.tsv'))[[1]];sp<-readRDS('reconstruction/cross_dataset/phase2_upr_rpe1/phase2_axis_spec.rds')$UPR$positive;v<-fread(file.path(w,'HepG2_gene_effects.tsv'));sy<-md$symbol;ui<-which(sy%in%u);gs<-c(sort(unique(v$gene))[1:8],'GBF1','ALG14','HSP90B1','MANF');controlrows<-which(md$gene=='non-targeting');f<-H5File$new(file.path(w,'HepG2_complete.h5ad'),'r');C<-rowsum(f[['X']][ui,controlrows,drop=FALSE],group=sy[ui],reorder=FALSE);C<-C[match(u,rownames(C)),,drop=FALSE];Lc<-colSums(C);cg<-md$gem[controlrows];ans<-list();set.seed(2026110705);testrows<-sample(seq_along(a$source_rows),40);V<-f[['X']][ui,a$source_rows[testrows],drop=FALSE];diffL<-max(abs(colSums(V)-a$L[testrows]));stopifnot(diffL==0)
for(g in gs){ii<-which(md$gene==g);T<-rowsum(f[['X']][ui,ii,drop=FALSE],group=sy[ui],reorder=FALSE);T<-T[match(u,rownames(T)),,drop=FALSE];L<-colSums(T);keep<-setdiff(sp,g);j<-match(g,u)
 for(normmode in c('exact_Lminus_target','fixed_L')){lt<-L;lc<-Lc;if(normmode=='exact_Lminus_target'&&!is.na(j)){lt<-lt-T[j,];lc<-lc-C[j,]};q<-apply(T[match(keep,u),,drop=FALSE],2,function(x)NA_real_);qt<-colMeans(log1p(T[match(keep,u),,drop=FALSE]*rep(1e4/lt,each=length(keep))));qc<-colMeans(log1p(C[match(keep,u),,drop=FALSE]*rep(1e4/lc,each=length(keep))));mu<-tapply(qc,cg,mean);d<-mean((qt-mu[md$gem[ii]])/sd(qc));published<-v[gene==g&mode==normmode,effect];ans[[length(ans)+1]]<-data.table(gene=g,mode=normmode,recomputed=d,published=published,abs_difference=abs(d-published))}}
f$close_all();z<-rbindlist(ans);fwrite(z,file.path(w,'independent_raw_count_QA.tsv'),sep='\t');stopifnot(max(z$abs_difference)<1e-10);writeLines(paste('Recounted libraries maxdifference',diffL,';twenty-four independent gene/mode reconstructions maxdifference',max(z$abs_difference)),file.path(w,'numerical_QA_summary.txt'))
